def separate_paren_groups(paren_string):
    groups = []
    current = []
    depth = 0

    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            current.append(ch)
            depth += 1
        elif ch == ')':
            current.append(ch)
            depth -= 1
            if depth == 0:
                groups.append(''.join(current))
                current = []

    return groups

