    cur = float(x)
    for _ in range(max_newton):
        y = poly(cur)
        if abs(y) < tol:
            return cur
        dy = dpoly(cur)
        if abs(dy) < 1e-12:
            break
        nxt = cur - y / dy
        if not math.isfinite(nxt):
            break
        if abs(nxt - cur) < tol and abs(poly(nxt)) < tol:
            return nxt
        cur = nxt

    # 牛顿法失败时，利用偶数次多项式必有实根的性质做区间扩张 + 二分
    left = float(x)
    right = float(x)
    f_left = poly(left)
    if abs(f_left) < tol:
