    max_expand = 200
    for _ in range(max_expand):
        left = x - step
        right = x + step
        f_left = poly(left)
        f_right = poly(right)

        if abs(f_left) < tol:
            return left
        if abs(f_right) < tol:
            return right

        if f_left * f_right < 0:
            break
